602:     /* ----- Réanimation de coéquipier ----- */
603:     const revivePrompt = document.getElementById('revivePrompt');
604:     const reviveLabel = document.getElementById('reviveLabel');
605:     const reviveFill = document.getElementById('reviveFill');
606:     const interactPrompt = document.getElementById('interactPrompt');
607: 
608:     function updateRevive(dt) {
609:         if (!player.alive || player.phase !== 'ground') {
610:             if (revivePrompt) revivePrompt.hidden = true;
611:             return;
612:         }
613: 
614:         // Si le joueur est lui-même K.O. :
615:         if (player.dbno) {
616:             if ((player.reviveProgress || 0) > 0) {
617:                 if (revivePrompt) revivePrompt.hidden = false;
618:                 if (reviveLabel) reviveLabel.textContent = 'UN COÉQUIPIER VOUS RÉANIME...';
619:                 if (reviveFill) reviveFill.style.width = `${Math.min(100, Math.round(player.reviveProgress / 5 * 100))}%`;
620:             } else {
621:                 if (revivePrompt) revivePrompt.hidden = true;
622:             }
623:             return;
624:         }
625: 
626:         // Le joueur est debout : chercher un allié K.O. à portée (<= 120 unités)
627:         const downed = fighters.find(f => f !== player && f.alive && f.dbno && f.team === player.team && Math.hypot(f.x - player.x, f.y - player.y) <= 120);
628: 
629:         if (downed) {
630:             const holdingE = input.keys?.has?.('KeyE') || input.keys?.has?.('KeyF');
631:             if (holdingE) {
632:                 // Réanimation en cours : cacher complètement le prompt "Maintenir pour réanimer"
633:                 if (interactPrompt) interactPrompt.hidden = true;
634:                 if (revivePrompt) revivePrompt.hidden = false;
635:                 if (reviveLabel) reviveLabel.textContent = `RÉANIMATION DE ${downed.name.toUpperCase()}...`;
636:                 const done = combat.revive(player, downed, dt);
637:                 if (reviveFill) reviveFill.style.width = `${Math.min(100, Math.round((downed.reviveProgress || 0) / 5 * 100))}%`;
638:                 if (done) {
639:                     if (revivePrompt) revivePrompt.hidden = true;
640:                     if (interactPrompt) interactPrompt.hidden = true;
641:                     if (isMultiplayer && gameWs?.readyState === WebSocket.OPEN) {
642:                         gameWs.send(JSON.stringify({
643:                             type: 'p_action',
644:                             action: 'revive_done',
645:                             targetId: downed.id
646:                         }));
647:                     }
648:                 }
649:             } else {
650:                 // Pas en train de maintenir E : afficher consigne
651:                 if (downed.reviveProgress > 0) downed.reviveProgress = 0;
652:                 if (revivePrompt) revivePrompt.hidden = true;
653:                 if (interactPrompt) {
654:                     interactPrompt.hidden = false;
655:                     const keyEl = interactPrompt.querySelector('.drop-key');
656:                     const textEl = interactPrompt.querySelector('.interact-text');
657:                     if (keyEl) keyEl.textContent = 'E';
658:                     if (textEl) textEl.textContent = `Maintenir pour réanimer ${downed.name}`;
659:                 }
660:             }
661:         } else {
662:             if (revivePrompt && !player.dbno) revivePrompt.hidden = true;
663:             if (interactPrompt && interactPrompt.querySelector('.interact-text')?.textContent?.includes('réanimer')) {
664:                 interactPrompt.hidden = true;
665:             }
666:         }
667:     }
