738:     /* ----- Petits effets liés aux personnages (atterrissage, pas, soins) ----- */
739:     function fighterEffects(dt) {
740:         for (const f of fighters) {
741:             if (f.hitFlash > 0) f.hitFlash = Math.max(0, f.hitFlash - dt * 5);
742:             if (!f.alive) continue;
743: 
744:             // Saut du vaisseau (joueur)
745:             if (f === player && f._prevPhase === 'ship' && f.phase === 'air') SFX.play('jump', { x: f.x, y: f.y });
746: 
747:             // Ouverture du planeur : l'altitude passe sous le seuil
748:             if (f.phase === 'air') {
749:                 const alt = f.altitude ?? 1;
750:                 if ((f._prevAlt ?? 1) >= GLIDER_ALT && alt < GLIDER_ALT) SFX.play('glider', { x: f.x, y: f.y });
751:                 f._prevAlt = alt;
752:             }
753: 
754:             // Atterrissage : nuage de poussière (et petite secousse pour le joueur)
755:             if (f._prevPhase === 'air' && f.phase === 'ground') {
756:                 effects.landing(f.x, f.y);
757:                 SFX.play('land', { x: f.x, y: f.y });
758:                 if (f === player) renderer.shake(6);
759:             }
760:             f._prevPhase = f.phase;
761:             if (f.phase !== 'ground') continue;
762: 
763:             // Pas : poussière sur la terre, ondulations dans l'eau
764:             if (f.moving) {
765:                 f._stepT = (f._stepT || 0) + dt;
766:                 if (f._stepT > STEP_TIME) {
767:                     f._stepT = 0;
768:                     effects.footstep(f.x - Math.cos(f.angle) * 10, f.y - Math.sin(f.angle) * 10, f.inWater);
769:                     SFX.play('step', { x: f.x, y: f.y, water: f.inWater, vol: f === player ? 0.8 : 0.55 });
770:                 }
771:             }
772: 
773:             // Soin en cours : petits "+" qui montent
774:             if (f.usingItem) {
775:                 f._healT = (f._healT || 0) + dt;
776:                 if (f._healT > 0.28) {
777:                     f._healT = 0;
778:                     const it = f.inventory[f.usingItem.slot];
779:                     const shield = (HEALS[it?.itemId]?.shield || 0) > 0;
780:                     if (roofAlphaAt(world, f.x, f.y) <= 0.5) effects.healTick(f.x, f.y, shield);
781:                     SFX.play('healTick', { x: f.x, y: f.y, shield });
782:                 }
783:             }
784:         }
785: 
786:         // Chiffres de dégâts (un par cible et par image), jaunes et plus gros si ça fait mal
787:         for (const [victim, d] of pendingDamage) {
788:             effects.damageNumber(victim.x, victim.y - victim.r - 14, d.amount, d.shield, d.amount >= 50);
789:         }
