31:     const ux = fx * fx * (3 - 2 * fx);
32:     const uy = fy * fy * (3 - 2 * fy);
33:     const a = hash2(ix, iy, seed);
34:     const b = hash2(ix + 1, iy, seed);
35:     const c = hash2(ix, iy + 1, seed);
36:     const d = hash2(ix + 1, iy + 1, seed);
37:     return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
38: }
