if (isMultiplayer && gameWs && gameWs.readyState === WebSocket.OPEN && (now - lastNetSync > 50)) {
    lastNetSync = now;
    gameWs.send(JSON.stringify({
        type: 'p_state',
        x: Math.round(player.x * 10) / 10,
        y: Math.round(player.y * 10) / 10,
        vx: Math.round(player.vx),
        vy: Math.round(player.vy),
        angle: Math.round(player.angle * 100) / 100,
        phase: player.phase,
        altitude: Math.round((player.altitude || 0) * 100) / 100,
        health: Math.round(player.health),
        shield: Math.round(player.shield),
        slot: player.slot,
        dbno: !!player.dbno,
        dbnoTimer: player.dbnoTimer || 0
    }));
}

// Synchronisation des bots par l'hôte (8 Hz)
if (isMultiplayer && isHost && gameWs && gameWs.readyState === WebSocket.OPEN && (now - lastBotSync > 125)) {
    lastBotSync = now;
    const bData = [];
    for (const b of bots.bots) {
        if (b.alive || b.dbno) {
            bData.push([
                b.id,
                Math.round(b.x),
                Math.round(b.y),
                Math.round(b.angle * 100) / 100,
                Math.round(b.health),
                Math.round(b.shield),
                b.phase,
                b.dbno ? 1 : 0,
                b.alive ? 1 : 0
            ]);
        }
    }
    if (bData.length > 0) {
        gameWs.send(JSON.stringify({
            type: 'b_sync',
            bots: bData
        }));
    }
}

