877:     /* ----- Petits effets liés aux personnages (atterrissage, pas, soins) ----- */
878:     function fighterEffects(dt) {
879:         for (const f of fighters) {
880:             if (f.hitFlash > 0) f.hitFlash = Math.max(0, f.hitFlash - dt * 5);
881:             if (!f.alive) continue;
882: 
883:             // Saut du vaisseau (joueur)
884:             if (f === player && f._prevPhase === 'ship' && f.phase === 'air') SFX.play('jump', { x: f.x, y: f.y });
885: 
886:             // Ouverture du planeur : l'altitude passe sous le seuil
887:             if (f.phase === 'air') {
888:                 const alt = f.altitude ?? 1;
889:                 if ((f._prevAlt ?? 1) >= GLIDER_ALT && alt < GLIDER_ALT) SFX.play('glider', { x: f.x, y: f.y });
890:                 f._prevAlt = alt;
891:             }
892: 
893:             // Atterrissage : nuage de poussière (et petite secousse pour le joueur)
894:             if (f._prevPhase === 'air' && f.phase === 'ground') {
895:                 effects.landing(f.x, f.y);
896:                 SFX.play('land', { x: f.x, y: f.y });
897:                 if (f === player) renderer.shake(6);
898:             }
899:             f._prevPhase = f.phase;
900:             if (f.phase !== 'ground') continue;
901: 
902:             // Pas : poussière sur la terre, ondulations dans l'eau
903:             if (f.moving) {
904:                 f._stepT = (f._stepT || 0) + dt;
905:                 if (f._stepT > STEP_TIME) {
906:                     f._stepT = 0;
907:                     effects.footstep(f.x - Math.cos(f.angle) * 10, f.y - Math.sin(f.angle) * 10, f.inWater);
908:                     SFX.play('step', { x: f.x, y: f.y, water: f.inWater, vol: f === player ? 0.8 : 0.55 });
909:                 }
910:             }
911: 
912:             // Soin en cours : petits "+" qui montent
913:             if (f.usingItem) {
914:                 f._healT = (f._healT || 0) + dt;
915:                 if (f._healT > 0.28) {
916:                     f._healT = 0;
917:                     const it = f.inventory[f.usingItem.slot];
918:                     const shield = (HEALS[it?.itemId]?.shield || 0) > 0;
919:                     if (roofAlphaAt(world, f.x, f.y) <= 0.5) effects.healTick(f.x, f.y, shield);
920:                     SFX.play('healTick', { x: f.x, y: f.y, shield });
921:                 }
922:             }
923:         }
924: 
925:         // Chiffres de dégâts (un par cible et par image), jaunes et plus gros si ça fait mal
926:         for (const [victim, d] of pendingDamage) {
927:             effects.damageNumber(victim.x, victim.y - victim.r - 14, d.amount, d.shield, d.amount >= 50);
928:         }
929:         pendingDamage.clear();
930: 
931:         for (const c of corpses) c.t += dt / DEATH_TIME;
932:         while (corpses.length && corpses[0].t >= 1) corpses.shift();
933:         if (hitmarker.t > 0) hitmarker.t = Math.max(0, hitmarker.t - dt * 4);
934:     }
