936:     /* ----- Fin de partie ----- */
937:     function checkEnd() {
938:         if (gameOver) return;
939: 
940:         if (teamMode) {
941:             const teamAlive = fighters.filter(f => f.alive && f.team === 1);
942:             const allStandingInTeam = teamAlive.filter(f => !f.dbno);
943:             const otherTeamsAlive = fighters.filter(f => f.alive && f.team !== 1);
944: 
945:             // Dès que le joueur meurt (éliminé), afficher l'écran de mort avec la possibilité
946:             // de cliquer sur "Regarder la partie" (ou Échap) pour suivre son coéquipier
947:             if (!player.alive && !playerDeathShown) {
948:                 playerDeathShown = true;
949:                 const remainingFighters = fighters.filter(f => f.alive).length;
950:                 stats.place = remainingFighters + 1;
951:                 if (stats.endT === null) stats.endT = time;
952:                 const target = allStandingInTeam[0] || teamAlive[0] || stats.killer;
953:                 if (target) {
954:                     setTimeout(() => {
955:                         if (!spectator.active) spectator.start(target);
956:                         if (target.alive) spectator.target = target;
957:                     }, SPECTATE_DELAY);
958:                 }
959:                 setTimeout(() => {
960:                     SFX.play('defeat');
961:                     endScreen.show(endResult(false));
962:                 }, DEFEAT_DELAY);
963:             }
964: 
965:             // Si le joueur est mort mais que l'escouade est toujours en jeu : spectateur sur un coéquipier
966:             if (!player.alive && allStandingInTeam.length > 0) {
967:                 if (!spectator.active) {
968:                     spectator.start(allStandingInTeam[0]);
969:                 }
970:                 if (!spectator.target || !spectator.target.alive) {
971:                     spectator.target = allStandingInTeam[0];
972:                 }
973:             }
974: 
975:             // Escouade du joueur complètement éliminée
976:             if (teamAlive.length === 0) {
977:                 gameOver = true;
978:                 const remainingFighters = fighters.filter(f => f.alive).length;
979:                 stats.place = remainingFighters + 1;
980:                 if (stats.endT === null) stats.endT = time;
981:                 if (!playerDeathShown) {
982:                     playerDeathShown = true;
983:                     setTimeout(() => spectator.start(stats.killer), SPECTATE_DELAY);
984:                     setTimeout(() => {
985:                         SFX.play('defeat');
986:                         endScreen.show(endResult(false));
987:                     }, DEFEAT_DELAY);
988:                 }
989:                 return;
990:             }
991: 
992:             // Victoire Royale ! Tous les ennemis sont éliminés
993:             if (otherTeamsAlive.length === 0) {
994:                 gameOver = true;
995:                 stats.place = 1;
996:                 stats.endT = time;
997:                 setTimeout(() => {
998:                     SFX.play('victory');
999:                     if (endScreen.shown) {
1000:                         endScreen.result.win = true;
1001:                         endScreen.result.place = 1;
1002:                         if (endScreen.el.kicker) endScreen.el.kicker.textContent = `Dernier debout sur ${fighters.length}`;
1003:                         if (endScreen.el.title) endScreen.el.title.textContent = 'Victoire Royale';
1004:                         if (endScreen.el.placeNum) endScreen.el.placeNum.textContent = '#1';
1005:                         endScreen.root.classList.add('is-win');
1006:                         endScreen.root.classList.remove('is-lost');
1007:                         endScreen.open();
1008:                     } else {
1009:                         endScreen.show(endResult(true));
1010:                     }
1011:                 }, VICTORY_DELAY);
1012:                 return;
1013:             }
1014:         } else {
1015:             const alive = fighters.filter(f => f.alive).length;
1016:             if (!player.alive) {
1017:                 gameOver = true;
1018:                 stats.place = alive + 1;
1019:                 if (stats.endT === null) stats.endT = time;
1020:                 // La caméra passe sur le tueur, puis l'écran de fin s'affiche par-dessus
1021:                 setTimeout(() => spectator.start(stats.killer), SPECTATE_DELAY);
1022:                 setTimeout(() => {
1023:                     SFX.play('defeat');
1024:                     endScreen.show(endResult(false));
1025:                 }, DEFEAT_DELAY);
1026:             } else if (alive === 1) {
1027:                 gameOver = true;
1028:                 stats.place = 1;
1029:                 stats.endT = time;
1030:                 setTimeout(() => {
1031:                     SFX.play('victory');
1032:                     endScreen.show(endResult(true));
1033:                 }, VICTORY_DELAY);
1034:             }
1035:         }
1036:     }
