1056:     /* ----- Sons d'ambiance (vaisseau, vent, compte à rebours, cœur, coffres, oiseaux) ----- */
1057:     let prevCanJump = false;
1058:     let lastTick = -1;
1059:     let heartT = 0;
1060:     let humT = 0;
1061:     let birdT = 5 + Math.random() * 7;
