1063:     // view : celui que suit la caméra (le joueur, ou la cible du spectateur)
1064:     function updateAudio(dt, view = player) {
1065:         SFX.setListener(view.x, view.y);
1066: 
1067:         // Moteur du vaisseau : plein dedans, puis de plus en plus loin
1068:         let ship = 0;
1069:         if (player.phase === 'ship') ship = 1;
1070:         else if (drop.ship.active) {
1071:             const d = Math.hypot(player.x - drop.ship.x, player.y - drop.ship.y);
1072:             ship = Math.max(0, 1 - d / SHIP_HEAR_DIST) * 0.8;
1073:         }
1074:         SFX.setLoop('ship', ship);
1075: 
1076:         // Vent : fort en chute libre, plus doux sous le planeur
1077:         const wind = player.alive && player.phase === 'air' ? (player.altitude > GLIDER_ALT ? 1 : 0.45) : 0;
1078:         SFX.setLoop('wind', wind);
1079: 
1080:         // Grondement de la corruption : plus fort quand on s'y enfonce
1081:         let corrupt = 0;
1082:         if (player.alive && player.phase !== 'ship' && !corruption.isSafe(player.x, player.y)) {
1083:             corrupt = 0.6 + 0.4 * Math.min(1, corruption.depth(player.x, player.y) / 600);
1084:         }
1085:         SFX.setLoop('corruption', corrupt);
1086: 
1087:         // Compte à rebours avant le saut automatique
1088:         const canJump = drop.canJump;
1089:         if (player.phase === 'ship' && canJump) {
1090:             if (!prevCanJump) SFX.play('jumpReady');
1091:             const s = Math.ceil(drop.timeLeft);
1092:             if (s <= 5 && s !== lastTick) SFX.play('tick', { final: s <= 1 });
1093:             lastTick = s;
1094:         }
1095:         prevCanJump = canJump;
1096: 
1097:         const onGround = player.alive && player.phase === 'ground';
1098: 
1099:         // Battement de cœur quand la vie est basse
1100:         if (onGround && player.health < LOW_HEALTH) {
1101:             heartT -= dt;
1102:             if (heartT <= 0) {
1103:                 heartT = HEARTBEAT_TIME;
1104:                 SFX.play('heartbeat');
1105:             }
1106:         } else {
1107:             heartT = 0; // le premier battement part tout de suite
1108:         }
1109: 
1110:         if (!onGround) return;
1111: 
1112:         // Bourdonnement du coffre fermé le plus proche
1113:         humT -= dt;
1114:         if (humT <= 0) {
1115:             humT = CHEST_HUM_TIME;
1116:             let best = null;
1117:             let bestD = CHEST_HUM_RANGE;
1118:             for (const c of loot.chests) {
1119:                 if (c.opened) continue;
1120:                 const d = Math.hypot(c.x - player.x, c.y - player.y);
1121:                 if (d < bestD) {
1122:                     bestD = d;
1123:                     best = c;
1124:                 }
1125:             }
1126:             if (best) SFX.play('chestHum', { x: best.x, y: best.y });
1127:         }
1128: 
1129:         // Oiseaux de temps en temps
1130:         birdT -= dt;
1131:         if (birdT <= 0) {
1132:             birdT = 5 + Math.random() * 7;
1133:             SFX.play('bird', { vol: 0.6 });
1134:         }
1135:     }
