1137:     // Croix blanche (rouge si élimination) autour du viseur quand on touche
1138:     function drawHitmarker(ctx) {
1139:         if (hitmarker.t <= 0 || !player.alive) return;
1140:         const aim = renderer.screenToWorld(input.mouse.x, input.mouse.y);
1141:         const k = hitmarker.t;
1142:         const z = 1 / renderer.zoom;           // taille constante à l'écran
1143:         const gap = (6 + (1 - k) * 6) * z;
1144:         const len = (8 + k * 4) * z;
1145:         ctx.save();
1146:         ctx.globalAlpha = Math.min(1, k * 1.6);
1147:         ctx.lineCap = 'round';
1148:         ctx.beginPath();
1149:         for (const [dx, dy] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
1150:             ctx.moveTo(aim.x + dx * gap, aim.y + dy * gap);
1151:             ctx.lineTo(aim.x + dx * (gap + len), aim.y + dy * (gap + len));
1152:         }
1153:         ctx.strokeStyle = 'rgba(10, 16, 48, 0.8)';
1154:         ctx.lineWidth = 6 * z;
1155:         ctx.stroke();
1156:         ctx.strokeStyle = hitmarker.kill ? '#ff5470' : '#ffffff';
1157:         ctx.lineWidth = 3 * z;
1158:         ctx.stroke();
1159:         ctx.restore();
1160:     }
