1162:     /* ----- Indicateurs de coéquipiers hors écran ----- */
1163:     function drawTeammateOffscreen(ctx) {
1164:         if (!teamMode || !player.alive) return;
1165:         const teammates = fighters.filter(f => f !== player && f.alive && f.team === 1);
1166:         if (!teammates.length) return;
1167: 
1168:         const sw = renderer.cssW;
1169:         const sh = renderer.cssH;
1170:         const margin = 55;
1171: 
1172:         ctx.save();
1173:         ctx.setTransform(1, 0, 0, 1, 0, 0); // Repère écran en pixels réels
1174: 
1175:         for (const mate of teammates) {
1176:             const sPos = renderer.worldToScreen(mate.x, mate.y);
1177:             const onScreen = sPos.x >= margin && sPos.x <= sw - margin &&
1178:                              sPos.y >= margin && sPos.y <= sh - margin;
1179:             if (onScreen) continue; // Déjà visible à l'écran
1180: 
1181:             const cx = sw / 2;
1182:             const cy = sh / 2;
1183:             const angle = Math.atan2(sPos.y - cy, sPos.x - cx);
1184:             const dx = Math.cos(angle);
1185:             const dy = Math.sin(angle);
1186: 
1187:             const halfW = sw / 2 - margin;
1188:             const halfH = sh / 2 - margin;
1189:             const scaleX = halfW / Math.max(0.0001, Math.abs(dx));
1190:             const scaleY = halfH / Math.max(0.0001, Math.abs(dy));
1191:             const scale = Math.min(scaleX, scaleY);
1192:             const px = cx + dx * scale;
1193:             const py = cy + dy * scale;
1194: 
1195:             const distM = Math.round(Math.hypot(mate.x - player.x, mate.y - player.y) / 40);
1196:             const isDbno = mate.dbno;
1197:             const SQUAD_SLOT_COLORS = { 1: '#00e5ff', 2: '#ffd21e', 3: '#ff4fd8', 4: '#00ff88' };
1198:             const teamCol = SQUAD_SLOT_COLORS[mate.squadSlot || 2] || '#ffd21e';
1199:             const col = isDbno ? '#ff334b' : teamCol;
1200: 
1201:             ctx.save();
1202:             ctx.translate(px, py);
1203: 
1204:             // Flèche pointant vers le coéquipier
1205:             ctx.save();
1206:             ctx.rotate(angle);
1207:             ctx.beginPath();
1208:             ctx.moveTo(14, 0);
1209:             ctx.lineTo(-8, -8);
1210:             ctx.lineTo(-4, 0);
1211:             ctx.lineTo(-8, 8);
1212:             ctx.closePath();
1213:             ctx.fillStyle = col;
1214:             ctx.fill();
1215:             ctx.strokeStyle = '#0a1030';
1216:             ctx.lineWidth = 3;
1217:             ctx.stroke();
1218:             ctx.restore();
1219: 
1220:             // Badge d'information
1221:             const badgeText = isDbno ? `⚠ ${mate.name} (${Math.ceil(mate.dbnoTimer)}s)` : `${mate.name} ${distM}m`;
1222:             ctx.font = 'bold 12px Rubik, sans-serif';
1223:             const txtWidth = ctx.measureText(badgeText).width;
1224:             const bw = txtWidth + 16;
1225:             const bh = 22;
1226: 
1227:             const badgeX = -dx * 32 - bw / 2;
1228:             const badgeY = -dy * 32 - bh / 2;
1229: 
1230:             ctx.fillStyle = 'rgba(10, 16, 40, 0.88)';
1231:             ctx.beginPath();
1232:             ctx.roundRect(badgeX, badgeY, bw, bh, 6);
1233:             ctx.fill();
1234:             ctx.strokeStyle = col;
1235:             ctx.lineWidth = 1.8;
1236:             ctx.stroke();
1237: 
1238:             ctx.fillStyle = col;
1239:             ctx.textAlign = 'center';
1240:             ctx.textBaseline = 'middle';
1241:             ctx.fillText(badgeText, badgeX + bw / 2, badgeY + bh / 2);
1242: 
1243:             ctx.restore();
1244:         }
1245:         ctx.restore();
1246:     }
