121: // Distance au carré entre un point et un segment (évite Math.hypot dans les boucles)
122: function segDist2(px, py, ax, ay, dx, dy, l2) {
123:     let t = l2 ? ((px - ax) * dx + (py - ay) * dy) / l2 : 0;
124:     t = t < 0 ? 0 : t > 1 ? 1 : t;
125:     const ex = px - (ax + t * dx);
126:     const ey = py - (ay + t * dy);
127:     return ex * ex + ey * ey;
128: }
