130: function segmentClear(world, ax, ay, bx, by, pad = 0) {
131:     const inflate = Math.max(pad, LOS_STEP / 2);
132:     const minX = Math.min(ax, bx);
133:     const maxX = Math.max(ax, bx);
134:     const minY = Math.min(ay, by);
135:     const maxY = Math.max(ay, by);
136:     const list = world.collide.query(minX - inflate, minY - inflate, maxX + inflate, maxY + inflate, _near);
137:     if (!list.length) return true;
138: 
139:     const dx = bx - ax;
140:     const dy = by - ay;
141:     const l2 = dx * dx + dy * dy;
142:     _rects.length = 0;
143:     for (let i = 0; i < list.length; i++) {
144:         const c = list[i];
145:         if (c.kind === 'circle') {
146:             const rr = c.r + pad;
147:             // Pré-filtre : cercle hors du rectangle englobant du segment => ne peut pas le toucher
148:             if (c.x + rr < minX || c.x - rr > maxX || c.y + rr < minY || c.y - rr > maxY) continue;
149:             if (segDist2(c.x, c.y, ax, ay, dx, dy, l2) < rr * rr) return false;
150:         } else if (c.x - inflate < maxX && c.x + c.w + inflate > minX &&
151:                    c.y - inflate < maxY && c.y + c.h + inflate > minY) {
152:             _rects.push(c);
153:         }
154:     }
155:     if (!_rects.length) return true;
156: 
157:     const steps = Math.max(1, Math.ceil(Math.sqrt(l2) / LOS_STEP));
158:     for (let i = 1; i <= steps; i++) {
159:         const px = ax + (dx * i) / steps;
160:         const py = ay + (dy * i) / steps;
161:         for (let k = 0; k < _rects.length; k++) {
162:             const c = _rects[k];
163:             if (px > c.x - inflate && px < c.x + c.w + inflate &&
164:                 py > c.y - inflate && py < c.y + c.h + inflate) return false;
165:         }
166:     }
167:     return true;
168: }
