310:                     ? names[i]
311:                     : `${names[i % names.length]}${1 + Math.floor(i / names.length)}`;
312:                 if (BOT_SKINS.length && Math.random() < BOT_SKIN_CHANCE) {
313:                     // ~1 bot sur 4 porte un skin du catalogue
314:                     const s = rpick(BOT_SKINS);
315:                     bot.colors = { ...s.game };
316:                     bot.skinStyle = s.style || 'default';
317:                 } else {
318:                     bot.colors = { skin: rpick(SKINS), hair: rpick(HAIRS), outfit: rpick(OUTFITS), pack: rpick(PACKS) };
319:                     bot.skinStyle = 'default';
320:                 }
321:             }
322:             bot.pickaxeSkin = rpick(['pioche-defaut', 'pioche-laser', 'pioche-royale', 'pioche-cosmique', 'pioche-maudite', 'pioche-bonbon']);
323:             if (bot.inventory?.[0]) bot.inventory[0].pickaxeSkin = bot.pickaxeSkin;
324:             bot.phase = 'ship';
325:             bot.altitude = 1;
326:             bot.angle = drop.angle;
327: 
328:             // Attribution des équipes
329:             if (i < teammateCount) {
330:                 bot.team = myTeam; // Coéquipier du joueur !
331:                 this.playerTeammates.push(bot);
332:             } else if (teamSize > 1) {
333:                 bot.team = enemySquadId;
334:                 if (!this.squadLeaders[enemySquadId]) this.squadLeaders[enemySquadId] = bot;
335:                 enemySquadFill++;
336:                 if (enemySquadFill >= teamSize) {
337:                     enemySquadId++;
338:                     enemySquadFill = 0;
339:                     currentSquadLand = null; // Nouvelle escouade ennemie
340:                 }
341:             } else {
342:                 bot.team = nextId + 10; // Solo : chaque bot a son équipe
343:             }
344: 
345:             // Atterrissage groupé en escouade
346:             let land;
347:             if (bot.team === myTeam) {
348:                 land = this.chooseLanding(enter, exit);
349:             } else if (teamSize > 1) {
350:                 if (!currentSquadLand) currentSquadLand = this.chooseLanding(enter, exit);
351:                 land = {
352:                     x: clamp(currentSquadLand.x + rand(-100, 100), LAND_MARGIN, WORLD_SIZE - LAND_MARGIN),
353:                     y: clamp(currentSquadLand.y + rand(-100, 100), LAND_MARGIN, WORLD_SIZE - LAND_MARGIN)
354:                 };
355:             } else {
356:                 land = this.chooseLanding(enter, exit);
357:             }
358: 
359:             bot.brain = this.makeBrain(bot, land, this.chooseJump(land, enter, exit));
360:             fighters.push(bot);
361:             this.bots.push(bot);
362:         }
363:     }
364: 
365:     makeBrain(bot, land, jumpAt) {
366:         return {
367:             land, jumpAt,
368:             input: new BotInput(),
369:             think: Math.random() * THINK_MIN, // décalé pour ne pas tous réfléchir en même temps
370:             state: 'roam',
371:             goal: null,
372:             roamGoal: { x: land.x, y: land.y },
373:             // cible
374:             target: null,
375:             targetDist: Infinity,
376:             react: 0,           // temps de réaction avant de tirer sur une nouvelle cible
377:             lostT: 0,           // on va voir où la cible a disparu
378:             chase: { x: 0, y: 0 },
379:             // butin
380:             lootTarget: null,
381:             lootTries: 0,
382:             lootStuck: 0,
383:             lootTime: 0,
384:             lootSearch: 0,
385:             ignored: new WeakSet(),
386:             // déplacement / visée
387:             mx: 0, my: 0,
388:             wantAim: null,
389:             steer: 0,
390:             steerSide: Math.random() < 0.5 ? -1 : 1,
391:             strafe: 1,
392:             strafeT: 0,
393:             distMul: rand(0.85, 1.15),
394:             prefDist: 380,
395:             aim: bot.angle,
396:             aimErr: 0,
397:             trigger: 0,
398:             burst: rand(0.5, 1.1),
399:             // blocage
400:             stuckT: 0, moveT: 0, sx: bot.x, sy: bot.y,
401:             unstuck: 0, ux: 0, uy: 0,
402:             // corruption : chaque bot a sa propre prudence (petit = part tôt)
403:             prudence: rand(0.3, 0.95),
404:             zoneFrac: rand(0.7, 0.85),   // point visé à 70-85 % du rayon depuis le centre
405:             zoneAng: rand(-0.4, 0.4),    // décalage angulaire : ils ne s'empilent pas tous au même endroit
406:             zoneRush: false,
407:             zoneGoal: null,
408:             zx: 0, zy: 0, zr: 0,         // zone pour laquelle zoneGoal a été calculé
409:             inStorm: false,
410:             stormDepth: 0
411:         };
412:     }
413: 
414:     /* ----- Choix du point d'atterrissage et du moment du saut ----- */
415: 
416:     chooseLanding(enter, exit) {
417:         const drop = this.drop;
418:         const A = drop.pointAt(0);
419:         const dirX = Math.cos(drop.angle);
420:         const dirY = Math.sin(drop.angle);
421: 
422:         // Villes atteignables depuis le trajet (4 s de chute à 520 ≈ 2000 unités)
423:         const towns = (this.world.towns || []).filter(t => {
424:             const d = clamp((t.x - A.x) * dirX + (t.y - A.y) * dirY, enter, exit);
425:             const p = drop.pointAt(d);
426:             return Math.hypot(t.x - p.x, t.y - p.y) < 1900;
427:         });
428: 
429:         if (towns.length && Math.random() < 0.7) {
430:             const t = rpick(towns);
431:             for (let k = 0; k < 10; k++) {
432:                 const a = Math.random() * Math.PI * 2;
433:                 const rr = Math.sqrt(Math.random()) * t.radius * 0.85;
434:                 const x = t.x + Math.cos(a) * rr;
435:                 const y = t.y + Math.sin(a) * rr;
436:                 if (isLand(x, y)) return { x, y };
437:             }
438:             return { x: t.x, y: t.y };
439:         }
440: 
441:         // Sinon : un point au hasard sur la terre ferme, pas trop loin du trajet
442:         for (let k = 0; k < 30; k++) {
443:             const p = drop.pointAt(rand(enter, exit));
444:             const off = rand(-1600, 1600);
445:             const x = clamp(p.x - dirY * off, LAND_MARGIN, WORLD_SIZE - LAND_MARGIN);
446:             const y = clamp(p.y + dirX * off, LAND_MARGIN, WORLD_SIZE - LAND_MARGIN);
447:             if (isLand(x, y)) return { x, y };
448:         }
449:         return { x: WORLD_SIZE / 2, y: WORLD_SIZE / 2 };
450:     }
451: 
452:     // Distance de saut au hasard, autour de l'aplomb de la zone visée
453:     chooseJump(land, enter, exit) {
454:         const drop = this.drop;
455:         const A = drop.pointAt(0);
456:         const along = (land.x - A.x) * Math.cos(drop.angle) + (land.y - A.y) * Math.sin(drop.angle);
457:         return clamp(along + rand(-700, 250), enter, exit);
458:     }
459: 
460:     /* ===================== MISE À JOUR ===================== */
461: 
462:     update(dt, time) {
463:         // Zone de référence commune à tous les bots pour cette image
464:         this._ref = this.zoneRef();
465:         const st = this.corruption ? this.corruption.state : 'idle';
466:         this._lootMargin = st === 'wait' || st === 'shrink' ? ZONE_LOOT_MARGIN : ZONE_MARGIN;
467: 
468:         for (const bot of this.bots) {
469:             if (!bot.alive) continue;
470:             if (bot.phase === 'ship') this.updateShip(bot);
471:             else if (bot.phase === 'air') this.updateAir(bot, dt);
472:             else this.updateGround(bot, dt, time);
473:         }
474:     }
475: 
476:     updateShip(bot) {
477:         const drop = this.drop;
478:         bot.x = clamp(drop.ship.x, 0, WORLD_SIZE);
479:         bot.y = clamp(drop.ship.y, 0, WORLD_SIZE);
480:         bot.angle = drop.angle;
481: 
482:         // Saut synchronisé pour les escouades
483:         let squadJump = false;
484:         if (bot.team === 1) {
485:             // Coéquipier du joueur : saute UNIQUEMENT quand le joueur saute !
486:             if (this.player && this.player.phase !== 'ship') {
487:                 squadJump = true;
488:                 const slotIdx = (bot.squadSlot || 2) - 1;
489:                 const side = slotIdx % 2 === 1 ? 1 : -1;
490:                 const offsetAng = (drop.angle || 0) + side * 1.5;
491:                 bot.brain.land = {
492:                     x: clamp(this.player.x + Math.cos(offsetAng) * 60, LAND_MARGIN, WORLD_SIZE - LAND_MARGIN),
493:                     y: clamp(this.player.y + Math.sin(offsetAng) * 60, LAND_MARGIN, WORLD_SIZE - LAND_MARGIN)
494:                 };
495:             }
496:         } else if (bot.team > 1) {
497:             // Escouade ennemie : saute avec son chef d'escouade
498:             const leader = this.squadLeaders[bot.team];
499:             if (leader && leader !== bot && leader.phase !== 'ship') {
500:                 squadJump = true;
501:                 if (leader.brain?.land) {
502:                     bot.brain.land = {
503:                         x: clamp(leader.brain.land.x + rand(-90, 90), LAND_MARGIN, WORLD_SIZE - LAND_MARGIN),
504:                         y: clamp(leader.brain.land.y + rand(-90, 90), LAND_MARGIN, WORLD_SIZE - LAND_MARGIN)
505:                     };
506:                 }
507:             }
508:         }
509: 
510:         // Le coéquipier allié ne saute JAMAIS tout seul prématurément !
511:         const shouldJump = bot.team === 1
512:             ? (squadJump || !drop.ship.active)
513:             : (squadJump || drop.dist >= bot.brain.jumpAt || !drop.ship.active);
514: 
515:         if (shouldJump) {
516:             bot.phase = 'air';
517:             bot.altitude = 1;
518:             bot.vx = Math.cos(drop.angle) * 200; // garde un peu l'élan du vaisseau
519:             bot.vy = Math.sin(drop.angle) * 200;
520:         }
521:     }
522: 
523:     updateAir(bot, dt) {
524:         const br = bot.brain;
525: 
526:         // Si le bot est coéquipier du joueur : plane EN FORMATION à côté du joueur !
527:         if (bot.team === 1 && this.player) {
528:             const slotIdx = (bot.squadSlot || 2) - 1;
529:             const side = (slotIdx % 2 === 1 ? 1 : -1);
530:             const distSide = 55 + slotIdx * 15;
531:             const pAngle = this.player.angle || this.drop.angle || 0;
532:             const sideAng = pAngle + side * 1.57;
533:             const targetX = this.player.x + Math.cos(sideAng) * distSide;
534:             const targetY = this.player.y + Math.sin(sideAng) * distSide;
535:             br.land = { x: targetX, y: targetY };
536: 
537:             // Synchronise l'altitude avec le joueur
538:             if (this.player.phase === 'air') {
539:                 bot.altitude = Math.max(0.02, this.player.altitude);
540:             } else if (this.player.phase === 'ground') {
541:                 bot.altitude = Math.max(0, bot.altitude - dt * 3.5); // touche terre immédiatement
542:             }
543:         }
544: 
545:         const dx = br.land.x - bot.x;
546:         const dy = br.land.y - bot.y;
547:         const d = Math.hypot(dx, dy);
548:         const speed = AIR_SPEED * Math.min(1, Math.max(0.4, d / 120));
549:         const ux = d > 1 ? dx / d : 0;
550:         const uy = d > 1 ? dy / d : 0;
551:         const k = Math.min(1, dt * 6);
552:         bot.vx += (ux * speed - bot.vx) * k;
553:         bot.vy += (uy * speed - bot.vy) * k;
554:         bot.x = clamp(bot.x + bot.vx * dt, bot.r, WORLD_SIZE - bot.r);
555:         bot.y = clamp(bot.y + bot.vy * dt, bot.r, WORLD_SIZE - bot.r);
556:         if (bot.vx * bot.vx + bot.vy * bot.vy > 900) bot.angle = Math.atan2(bot.vy, bot.vx);
557:         bot.moving = false;
558:         bot.altitude -= dt / FALL_TIME;
559: 
560:         if (bot.altitude <= 0) {
561:             bot.altitude = 0;
562:             bot.phase = 'ground';
563:             bot.vx *= 0.3;
564:             bot.vy *= 0.3;
565:             br.aim = bot.angle;
566:             br.sx = bot.x;
567:             br.sy = bot.y;
568:             br.think = Math.random() * 0.2;
569:         }
570:     }
571: 
572:     updateGround(bot, dt) {
573:         const br = bot.brain;
574: 
575:         // ----- Bot K.O. : rampe lentement sans tirer -----
576:         if (bot.dbno) {
577:             const ally = this.fighters.find(f => f.alive && !f.dbno && f.team === bot.team);
578:             let gx = bot.x, gy = bot.y;
579:             if (ally) {
580:                 gx = ally.x; gy = ally.y;
581:             } else if (br.zoneGoal) {
582:                 gx = br.zoneGoal.x; gy = br.zoneGoal.y;
583:             }
584:             const dx = gx - bot.x;
585:             const dy = gy - bot.y;
586:             const d = Math.hypot(dx, dy);
587:             br.input.x = d > 10 ? dx / d : 0;
588:             br.input.y = d > 10 ? dy / d : 0;
589:             if (d > 10) bot.angle = Math.atan2(dy, dx);
590:             bot.update(dt, br.input, this.world, bot.x + Math.cos(bot.angle) * 50, bot.y + Math.sin(bot.angle) * 50);
591:             return;
592:         }
593: 
594:         // ----- Réanimation d'un allié en cours -----
595:         if (br.state === 'revive' && br.reviveTarget) {
596:             const tgt = br.reviveTarget;
597:             if (!tgt.alive || !tgt.dbno) {
598:                 br.state = 'roam';
599:                 br.reviveTarget = null;
600:             } else {
601:                 const distToTgt = Math.hypot(tgt.x - bot.x, tgt.y - bot.y);
602:                 if (distToTgt <= 90) {
603:                     br.input.x = 0;
604:                     br.input.y = 0;
605:                     br.aim = Math.atan2(tgt.y - bot.y, tgt.x - bot.x);
606:                     bot.update(dt, br.input, this.world, tgt.x, tgt.y);
607:                     const done = this.combat.revive(bot, tgt, dt);
608:                     if (done) {
609:                         br.state = 'roam';
610:                         br.reviveTarget = null;
611:                     }
612:                     return;
613:                 } else {
614:                     // Courir activement vers le coéquipier K.O.
615:                     br.goal = { x: tgt.x, y: tgt.y };
616:                 }
617:             }
618:         }
619: 
620:         // ----- Réflexion espacée -----
621:         br.think -= dt;
622:         if (br.think <= 0) {
623:             const step = THINK_MIN + Math.random() * THINK_RAND;
624:             br.think += step;
625:             this.think(bot, step);
626:         }
627:         br.react -= dt;
628:         br.trigger -= dt;
629:         br.unstuck -= dt;
630: 
631:         // ----- Direction voulue (recalculée à chaque image, la cible bouge) -----
632:         this.baseDirection(bot);
633:         let mx = br.mx;
634:         let my = br.my;
635:         if (br.unstuck > 0) {
636:             mx = br.ux;
637:             my = br.uy;
638:         } else if (br.steer && (mx || my)) {
639:             const c = Math.cos(br.steer);
640:             const s = Math.sin(br.steer);
641:             const nx = mx * c - my * s;
642:             my = mx * s + my * c;
643:             mx = nx;
644:         }
645:         const len = Math.hypot(mx, my);
646:         br.input.x = len > 0.01 ? mx / len : 0;
647:         br.input.y = len > 0.01 ? my / len : 0;
648: 
649:         // ----- Visée (tourne progressivement) -----
650:         let want = br.wantAim;
651:         if (want === null) want = len > 0.01 ? Math.atan2(my, mx) : br.aim;
652:         br.aim = turnToward(br.aim, want, TURN_SPEED * dt);
653: 
654:         bot.update(dt, br.input, this.world, bot.x + Math.cos(br.aim) * 100, bot.y + Math.sin(br.aim) * 100);
655: 
656:         this.shoot(bot, dt, want);
657: 
658:         // ----- Bloqué ? (a très peu bougé en 1,5 s alors qu'il voulait avancer) -----
659:         br.stuckT += dt;
660:         if (len > 0.01) br.moveT += dt;
661:         if (br.stuckT >= STUCK_TIME) {
662:             const moved = Math.hypot(bot.x - br.sx, bot.y - br.sy);
663:             if (moved < STUCK_DIST && br.moveT > STUCK_TIME * 0.7) this.unstick(bot);
664:             br.stuckT = 0;
665:             br.moveT = 0;
666:             br.sx = bot.x;
667:             br.sy = bot.y;
668:         }
669:     }
670: 
671:     /* ----- Le "cerveau" : ~4 fois par seconde ----- */
672: 
673:     think(bot, step) {
674:         if (bot.dbno) return; // Un bot K.O. ne réfléchit pas aux actions de combat
675:         const br = bot.brain;
676:         br.lostT -= step;
677:         br.aimErr = (Math.random() * 2 - 1) * AIM_ERROR;
678:         br.strafeT -= step;
679:         if (br.strafeT <= 0) {
680:             br.strafe = Math.random() < 0.5 ? -1 : 1;
681:             br.strafeT = rand(0.7, 1.8);
682:         }
683: 
684:         // 1) Cible visible la plus proche
685:         this.findTarget(bot);
686:         const t = br.target;
687:         const dist = br.targetDist;
688: 
689:         // 0) Allié à terre à réanimer ? (priorité maximale pour sauver le joueur ou l'escouade)
690:         const downedTeammate = this.fighters.find(f =>
691:             f !== bot && f.alive && f.dbno && f.team === bot.team
692:         );
693:         if (downedTeammate && (downedTeammate === this.player || !t || dist > 180)) {
694:             br.state = 'revive';
695:             br.reviveTarget = downedTeammate;
696:             br.goal = { x: downedTeammate.x, y: downedTeammate.y };
697:             this.baseDirection(bot);
698:             this.computeSteer(bot);
699:             return;
700:         } else if (br.state === 'revive' && (!br.reviveTarget || !br.reviveTarget.alive || !br.reviveTarget.dbno)) {
701:             br.state = 'roam';
702:             br.reviveTarget = null;
703:         }
704: 
705:         // 2) Meilleure arme (sans interrompre un soin ou un rechargement)
706:         const gunSlot = bestGunSlot(bot, t ? dist : null);
707:         const hasGun = gunSlot > 0;
708:         if (!bot.usingItem && !(bot.reloadTimer > 0) && bot.slot !== gunSlot) bot.slot = gunSlot;
709: 
710:         // 3) Rechargement : chargeur vide, ou à moitié vide quand c'est calme
711:         const cur = bot.inventory[bot.slot];
712:         const w = weaponAt(bot, bot.slot);
713:         if (w && w.type === 'gun' && !bot.usingItem && !(bot.reloadTimer > 0)) {
714:             const reserve = bot.ammo[w.ammo] || 0;
715:             if (reserve > 0 && ((cur.mag || 0) <= 0 || (!t && (cur.mag || 0) < (w.magSize || 1) * 0.6))) {
716:                 this.combat.startReload(bot);
717:             }
718:         }
719: 
720:         // 4) Corruption : faut-il rejoindre la zone ? (met à jour br.zoneRush / zoneGoal)
721:         const rush = this.zoneThink(bot);
722:         // Ennemi très proche : on se bat (en se rapprochant de la zone), sauf loin dans la corruption
723:         const close = t && dist < ZONE_FIGHT_DIST && br.stormDepth < ZONE_DEEP;
724:         if (bot.usingItem && rush && br.inStorm && !this.stormHealOk(bot)) {
725:             // Soin interrompu (changer de case l'annule aussi dans combat.js) : il faut courir
726:             bot.usingItem = null;
727:             bot.slot = gunSlot;
728:         }
729: 
730:         // 5) Décision
731:         if (bot.usingItem) {
732:             br.state = 'heal';
733:         } else if (rush && !close) {
734:             // Rejoindre la zone passe avant le pillage et les combats lointains
735:             // (on tire quand même en courant si une cible est en vue)
736:             br.state = 'zone';
737:             br.goal = br.zoneGoal;
738:             if (!t && this.stormHealOk(bot)) {
739:                 const healSlot = this.pickHeal(bot, br.inStorm);
740:                 if (healSlot > 0) {
741:                     const prev = bot.slot;
742:                     bot.slot = healSlot;
743:                     if (this.combat.startUse(bot)) br.state = 'heal'; // se soigne en marchant vers la zone
744:                     else bot.slot = prev;
745:                 }
746:             }
747:         } else if (t && hasGun) {
748:             br.state = 'fight';
749:             br.prefDist = prefDistFor(WEAPONS[bot.inventory[gunSlot].weaponId], br.distMul);
750:         } else {
751:             const healSlot = t ? -1 : this.pickHeal(bot);
752:             if (healSlot > 0) {
753:                 bot.slot = healSlot;
754:                 this.combat.startUse(bot);
755:                 br.state = 'heal';
756:             } else {
757:                 const pDist = (bot.team === 1 && this.player) ? Math.hypot(this.player.x - bot.x, this.player.y - bot.y) : 0;
758:                 const lootRadius = bot.team === 1 ? (pDist > 220 ? 280 : LOOT_SEARCH) : (hasGun ? LOOT_BONUS : LOOT_SEARCH);
759:                 const lt = this.updateLootTarget(bot, lootRadius, step);
760:                 const ltDist = lt ? Math.hypot(lt.x - bot.x, lt.y - bot.y) : Infinity;
761:                 if (t && dist < 280 && (dist < 160 || ltDist > dist)) {
762:                     br.state = 'melee'; // seulement la pioche et la cible est proche : on fonce
763:                     if (lt && ltDist < 110) this.tryInteract(bot, lt); // ramasse une arme en plein combat
764:                 } else if (lt) {
765:                     br.state = 'loot';
766:                     br.goal = lt;
767:                     this.tryInteract(bot, lt);
768:                 } else if (t) {
769:                     br.state = 'flee';
770:                 } else {
771:                     br.state = 'roam';
772:                     // Cohésion d'escouade : les coéquipiers du joueur restent proches du joueur
773:                     if (bot.team === 1 && this.player && this.player.alive && !this.player.dbno) {
774:                         if (pDist > 240) {
775:                             br.roamGoal = { x: this.player.x + rand(-70, 70), y: this.player.y + rand(-70, 70) };
776:                             br.goal = br.roamGoal;
777:                         } else if (pDist > 140) {
778:                             if (!br.roamGoal || Math.hypot(br.roamGoal.x - bot.x, br.roamGoal.y - bot.y) < 60) {
779:                                 br.roamGoal = { x: this.player.x + rand(-120, 120), y: this.player.y + rand(-120, 120) };
780:                             }
781:                             br.goal = br.roamGoal;
782:                         } else {
783:                             const g = br.roamGoal;
784:                             if (!g || Math.hypot(g.x - bot.x, g.y - bot.y) < 50 ||
785:                                 !this.inZone(g.x, g.y, ZONE_MARGIN)) br.roamGoal = { x: this.player.x + rand(-100, 100), y: this.player.y + rand(-100, 100) };
786:                             br.goal = br.roamGoal;
