170: // aucun état à mémoriser par combattant.
171: // Performance : ce dessin est fait pour CHAQUE combattant en l'air (jusqu'à 25 à la fois) :
172: // pas de tableau temporaire, opacités via globalAlpha (pas de couleur "rgba(...)" recréée),
173: // contours d'aile précalculés, et rien n'est dessiné hors écran.
174: 
175: const TAU = Math.PI * 2;
176: const OPEN_ALT = 0.45;    // le planeur s'ouvre sous cette altitude
177: const DEPLOY_ALT = 0.07;  // "durée" du déploiement, mesurée en altitude
178: const FOLD_ALT = 0.035;   // il se replie juste avant de toucher le sol
179: const PANELS = 3;         // panneaux colorés par demi-aile
180: const FRAME = '#1d2440';  // armature sombre du planeur
181: const SHADOW = 'rgb(12, 24, 40)';
182: const SIDES = [-1, 1];      // gauche puis droite
183: const WING_SIDES = [1, -1]; // aile droite puis aile gauche
184: 
185: function smoothstep(a, b, v) {
186:     const t = clamp((v - a) / (b - a), 0, 1);
187:     return t * t * (3 - 2 * t);
188: }
189: 
190: // Dépasse un peu la taille finale puis revient (effet rebond)
191: function easeOutBack(t) {
192:     const c1 = 1.70158;
193:     const c3 = c1 + 1;
194:     const u = t - 1;
195:     return 1 + c3 * u * u * u + c1 * u * u;
196: }
197: 
198: // Écart entre 2 angles ramené dans [-π, π]
199: function angleDiff(a, b) {
200:     return ((((a - b) % TAU) + TAU * 1.5) % TAU) - Math.PI;
201: }
202: 
203: function fillStroke(ctx, fill, lw = 3) {
204:     ctx.fillStyle = fill;
205:     ctx.fill();
206:     ctx.strokeStyle = OUTLINE;
207:     ctx.lineWidth = lw;
208:     ctx.stroke();
209: }
210: 
211: // Membre en trait épais arrondi (hanche → genou → pied) : contour sombre puis couleur par-dessus
212: function limb(ctx, x0, y0, x1, y1, x2, y2, width, color) {
213:     ctx.beginPath();
214:     ctx.moveTo(x0, y0);
215:     ctx.lineTo(x1, y1);
216:     ctx.lineTo(x2, y2);
217:     ctx.strokeStyle = OUTLINE;
218:     ctx.lineWidth = width + 6;
219:     ctx.stroke();
220:     ctx.strokeStyle = color;
221:     ctx.lineWidth = width;
222:     ctx.stroke();
223: }
224: 
225: function hexRGB(c) {
226:     if (typeof c !== 'string' || c[0] !== '#') return null;
227:     let h = c.slice(1);
228:     if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
229:     if (h.length !== 6) return null;
230:     const n = parseInt(h, 16);
231:     return Number.isNaN(n) ? null : [(n >> 16) & 255, (n >> 8) & 255, n & 255];
232: }
233: 
234: // 2 couleurs de panneaux : jaune + couleur du sac, ou couleur du sac + bleu si le sac est clair
235: // (mémorisées par couleur de sac : calculées une seule fois)
236: const gliderCache = new Map();
237: function gliderColors(pack) {
238:     let res = gliderCache.get(pack);
239:     if (res) return res;
240:     const c = hexRGB(pack);
241:     if (!c) {
242:         res = ['#ffe03d', '#3a8dff'];
243:     } else {
244:         const lum = (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) / 255;
245:         res = lum > 0.6 ? [pack, '#3a8dff'] : ['#ffe03d', pack];
246:     }
247:     if (gliderCache.size < 64) gliderCache.set(pack, res);
248:     return res;
249: }
250: 
251: // Joueur (ou bot) en chute : chute libre en étoile, puis planeur façon Fortnite
252: export function drawFalling(ctx, p, time) {
253:     const alt = clamp(p.altitude || 0, 0, 1);
254:     const r = p.r || 26;
255:     const s = 1 + alt * 0.9;             // plus gros quand il est haut
256:     // Hors de la vue de l'image en cours (voir utils.frameView) : rien à dessiner.
257:     // Marge : envergure + lignes de vent + traînées + décalage de l'ombre.
258:     if (!inFrameView(p.x, p.y, r * s * 6 + 80)) return;
259: 
260:     const f = {
261:         t: time || 0,
262:         alt,
263:         r,
264:         vx: p.vx || 0,
265:         vy: p.vy || 0,
266:         speed: Math.hypot(p.vx || 0, p.vy || 0),
267:         s,
268:         sh: 0.45 + 0.55 * (1 - alt),     // l'ombre grossit en se rapprochant...
269:         shA: 0.1 + (1 - alt) * 0.16,     // ... et devient plus nette
270:         shx: p.x + alt * 40,             // décalage de l'ombre (soleil en haut à gauche)
271:         shy: p.y + alt * 55
272:     };
273: 
274:     ctx.save();
275:     ctx.lineJoin = 'round';
276:     if (alt > OPEN_ALT) drawSkydiver(ctx, p, f);
277:     else drawGliding(ctx, p, f);
278:     ctx.restore();
279: }
280: 
281: /* ----- Chute libre ----- */
282: 
283: // Orientation : sens du déplacement si on va assez vite, sinon la visée (transition douce)
284: function fallHeading(p, speed) {
285:     const aim = p.angle || 0;
286:     if (speed < 1) return aim;
287:     const w = smoothstep(40, 140, speed);
288:     return aim + angleDiff(Math.atan2(p.vy, p.vx), aim) * w;
289: }
290: 
291: // Petit battement des membres dans le vent
292: function flutter(t, seed, i, freq) {
293:     return Math.sin(t * freq + seed + i * 1.9);
294: }
295: 
296: function drawSkydiver(ctx, p, f) {
297:     const { t, r, s } = f;
298:     const heading = fallHeading(p, f.speed);
299:     const seed = (p.id || 0) * 1.37;
300:     const col = p.colors || {};
301:     const skin = col.skin || '#f2c29b';
302:     const hair = col.hair || '#5a3419';
303:     const outfit = col.outfit || '#ff7a1a';
304:     const pack = col.pack || '#3a8dff';
305: 
306:     // Ombre au sol
307:     const ga = ctx.globalAlpha;
308:     ctx.fillStyle = SHADOW;
309:     ctx.globalAlpha = ga * f.shA;
310:     ctx.beginPath();
311:     ctx.ellipse(f.shx, f.shy, r * 1.45 * f.sh, r * 1.3 * f.sh, heading, 0, TAU);
312:     ctx.fill();
313:     ctx.globalAlpha = ga;
314: 
315:     ctx.save();
316:     ctx.translate(p.x, p.y);
317:     ctx.scale(s, s);
318:     ctx.lineCap = 'round';
319:     drawWind(ctx, f, false); // lignes de vent derrière le personnage
320: 
321:     ctx.save();
322:     // Léger roulis du corps dans le vent
323:     ctx.rotate(heading + Math.sin(t * 2.1 + seed) * 0.07);
324: 
325:     // Jambes écartées vers l'arrière (hanche → genou → pied)
326:     for (const sd of SIDES) {
327:         const i = sd > 0 ? 0 : 2;
328:         const hx = -r * 0.5;
329:         const hy = sd * r * 0.26;
330:         const a1 = sd * (2.45 + flutter(t, seed, i, 7.5) * 0.1);
331:         const kx = hx + Math.cos(a1) * r * 0.62;
332:         const ky = hy + Math.sin(a1) * r * 0.62;
333:         const a2 = sd * (2.8 + flutter(t, seed, i + 1, 9.3) * 0.14);
334:         const fx = kx + Math.cos(a2) * r * 0.58;
335:         const fy = ky + Math.sin(a2) * r * 0.58;
336:         limb(ctx, hx, hy, kx, ky, fx, fy, r * 0.4, outfit);
337:         ctx.beginPath();
338:         ctx.ellipse(fx, fy, r * 0.25, r * 0.17, a2, 0, TAU);
339:         fillStroke(ctx, skin);
340:     }
341: 
342:     // Bras écartés, coudes pliés vers l'avant (épaule → coude → main)
343:     for (const sd of SIDES) {
344:         const i = sd > 0 ? 4 : 6;
345:         const sx = r * 0.28;
346:         const sy = sd * r * 0.4;
347:         const a1 = sd * (1.35 + flutter(t, seed, i, 8.1) * 0.12);
348:         const ex = sx + Math.cos(a1) * r * 0.6;
349:         const ey = sy + Math.sin(a1) * r * 0.6;
350:         const a2 = sd * (0.6 + flutter(t, seed, i + 1, 10.2) * 0.16);
351:         const hx = ex + Math.cos(a2) * r * 0.58;
352:         const hy = ey + Math.sin(a2) * r * 0.58;
353:         limb(ctx, sx, sy, ex, ey, hx, hy, r * 0.34, outfit);
354:         ctx.beginPath();
355:         ctx.arc(hx, hy, r * 0.24, 0, TAU);
356:         fillStroke(ctx, skin);
357:     }
358: 
359:     // Torse
360:     ctx.beginPath();
361:     ctx.ellipse(-r * 0.05, 0, r * 0.7, r * 0.52, 0, 0, TAU);
362:     fillStroke(ctx, outfit);
363: 
364:     // Sac à dos (on le voit de dos) + petit reflet
365:     ctx.beginPath();
366:     ctx.roundRect(-r * 0.52, -r * 0.38, r * 0.72, r * 0.76, r * 0.2);
367:     fillStroke(ctx, pack);
368:     ctx.beginPath();
369:     ctx.ellipse(-r * 0.3, -r * 0.18, r * 0.14, r * 0.08, 0, 0, TAU);
370:     ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
371:     ctx.fill();
372: 
373:     // Tête : skin (heaume, crâne, cagoule, casque) si le combattant en porte un...
374:     if (!drawStyledHead(ctx, p, r * 0.4, t, r * 0.8)) {
375:         // ... sinon tête vue de dos : surtout les cheveux, un peu de peau à l'avant
376:         ctx.beginPath();
377:         ctx.arc(r * 0.8, 0, r * 0.4, 0, TAU);
378:         ctx.fillStyle = skin;
379:         ctx.fill();
380:         ctx.save();
381:         ctx.clip();
382:         ctx.beginPath();
383:         ctx.arc(r * 0.68, 0, r * 0.42, 0, TAU);
384:         ctx.fillStyle = hair;
385:         ctx.fill();
386:         ctx.restore();
387:         ctx.beginPath();
388:         ctx.arc(r * 0.8, 0, r * 0.4, 0, TAU);
389:         ctx.strokeStyle = OUTLINE;
390:         ctx.lineWidth = 3;
391:         ctx.stroke();
392:     }
393:     ctx.restore();
394: 
395:     drawWind(ctx, f, true); // lignes de vent devant le personnage
396:     ctx.restore();
397: }
398: 
399: // Lignes de vent : l'air remonte vers la caméra (elles s'écartent du personnage)
400: // et part à l'opposé du déplacement horizontal. front = moitié dessinée par-dessus.
401: function drawWind(ctx, f, front) {
402:     const { t, r, speed } = f;
403:     const k = Math.min(1, speed / AIR_SPEED);
404:     const bx = speed > 1 ? (-f.vx / speed) * k : 0;
405:     const by = speed > 1 ? (-f.vy / speed) * k : 0;
406:     const ga = ctx.globalAlpha;
407:     ctx.strokeStyle = '#ffffff';
408:     ctx.lineWidth = 2.5;
409:     for (let i = front ? 1 : 0; i < 14; i += 2) {
410:         const cyc = t * 1.6 + i * 0.618;
411:         const ph = cyc % 1;
412:         // Nouvel angle à chaque passage pour éviter un motif répétitif
413:         const a = i * 2.39996 + Math.floor(cyc) * 1.1;
414:         const ox = Math.cos(a);
415:         const oy = Math.sin(a);
416:         const dist = r * (1.2 + ph * 2.4);
417:         const cx = ox * dist + bx * ph * r * 2.5;
418:         const cy = oy * dist + by * ph * r * 2.5;
419:         let mx = ox + bx * 2;
420:         let my = oy + by * 2;
421:         const ml = Math.hypot(mx, my) || 1;
422:         mx /= ml;
423:         my /= ml;
424:         const len = r * (0.45 + ph * 0.8);
425:         ctx.globalAlpha = ga * Math.sin(ph * Math.PI) * 0.55;
426:         ctx.beginPath();
427:         ctx.moveTo(cx - mx * len * 0.5, cy - my * len * 0.5);
428:         ctx.lineTo(cx + mx * len * 0.5, cy + my * len * 0.5);
429:         ctx.stroke();
430:     }
431:     ctx.globalAlpha = ga;
432: }
433: 
434: /* ----- Planeur ----- */
435: 
436: // Point de l'aile (repère du planeur, +x = avant), EN RAYONS, pour l'aile droite à envergure 1.
437: // u = 0 au centre → 1 au bout de l'aile, lead = bord d'attaque (sinon bord de fuite).
438: // Point réel : x = r * wingX(u, lead), y = side * span * r * wingY(u, lead)
439: // (side = +1 aile droite / -1 aile gauche ; demi-envergure ≈ 2,25 × r)
440: function wingX(u, lead) {
441:     return lead
442:         ? 1.65 - 2.0 * u + Math.sin(u * Math.PI) * 0.22
443:         : 0.7 - 1.45 * u + Math.sin(u * Math.PI) * 0.1;
444: }
445: 
446: function wingY(u, lead) {
447:     return lead ? 2.25 * u : 2.25 * u * 0.94;
448: }
449: 
450: // Contour d'un morceau de demi-aile (panneaux j0 à j1 exclu), en rayons : [x0, y0, x1, y1, ...]
451: // Le bord de fuite est festonné (petit creux entre deux nervures, comme une toile tendue).
452: // Tout est linéaire en r (x) et en side × span × r (y) : calculé UNE fois, puis mis à l'échelle.
453: function unitWingPoly(j0, j1) {
454:     const pts = [];
455:     const steps = (j1 - j0) * 3;
456:     for (let i = 0; i <= steps; i++) {
457:         const u = (j0 + ((j1 - j0) * i) / steps) / PANELS;
458:         pts.push(wingX(u, true), wingY(u, true));
459:     }
460:     for (let j = j1; j > j0; j--) {
461:         const ax = wingX(j / PANELS, false);
462:         const ay = wingY(j / PANELS, false);
463:         const bx = wingX((j - 1) / PANELS, false);
464:         const by = wingY((j - 1) / PANELS, false);
465:         const cx = (ax + bx) / 2 + 0.16;
466:         const cy = (ay + by) / 2;
467:         for (let k = j === j1 ? 0 : 1; k <= 4; k++) {
468:             const s = k / 4;
469:             const m = 1 - s;
470:             pts.push(m * m * ax + 2 * m * s * cx + s * s * bx, m * m * ay + 2 * m * s * cy + s * s * by);
471:         }
472:     }
473:     return new Float32Array(pts);
474: }
475: 
476: const WING_HALF = unitWingPoly(0, PANELS);
477: const WING_PANELS = [];
478: for (let j = 0; j < PANELS; j++) WING_PANELS.push(unitWingPoly(j, j + 1));
479: 
480: // Ajoute le polygone (mis à l'échelle sx, sy) au chemin en cours. L'aile gauche est parcourue
481: // à l'envers pour que tout tourne dans le même sens (union propre avec d'autres formes).
482: function tracePoly(ctx, pts, sx, sy, reverse) {
483:     const n = pts.length / 2;
484:     for (let i = 0; i < n; i++) {
485:         const k = reverse ? n - 1 - i : i;
486:         const x = pts[k * 2] * sx;
487:         const y = pts[k * 2 + 1] * sy;
488:         if (i === 0) ctx.moveTo(x, y);
489:         else ctx.lineTo(x, y);
490:     }
491:     ctx.closePath();
492: }
493: 
494: function drawGliding(ctx, p, f) {
495:     const { t, alt, r, s } = f;
496:     const aim = p.angle || 0;
497:     const seed = (p.id || 0) * 1.37;
498: 
499:     // Déploiement avec rebond, puis repli juste avant le sol
500:     const dp = clamp((OPEN_ALT - alt) / DEPLOY_ALT, 0, 1);
501:     const gs = Math.max(0, easeOutBack(dp)) * smoothstep(0, FOLD_ALT, alt);
502: 
503:     // Inclinaison : vitesse latérale par rapport à la visée (+ = vers la droite)
504:     const lat = -f.vx * Math.sin(aim) + f.vy * Math.cos(aim);
505:     const bank = clamp(lat / AIR_SPEED, -1, 1);
506:     const sway = Math.sin(t * 2.2 + seed) * 0.045;                        // balancement
507:     const yaw = bank * 0.22 + sway;                                       // le nez suit le virage
508:     const off = bank * r * 0.25 + Math.sin(t * 1.7 + seed) * r * 0.05;    // glisse vers l'intérieur
509:     // Perspective : l'aile qui descend paraît plus courte, celle qui monte plus longue
510:     const flat = 1 - 0.08 * Math.abs(bank);
511:     const spanR = (1 - 0.2 * bank) * flat;
512:     const spanL = (1 + 0.2 * bank) * flat;
513:     // Planeur choisi dans le casier (joueur), sinon couleurs tirées du sac
514:     const colors = p.gliderColors || gliderColors(p.colors && p.colors.pack);
515: 
516:     // ----- Ombre au sol : personnage + aile, en un seul bloc -----
517:     ctx.save();
518:     ctx.translate(f.shx, f.shy);
519:     ctx.rotate(aim + yaw);
520:     ctx.scale(f.sh, f.sh);
521:     ctx.beginPath();
522:     ctx.moveTo(r * 0.95, 0);
523:     ctx.ellipse(0, 0, r * 0.95, r * 0.9, 0, 0, TAU);
524:     if (gs > 0.01) {
525:         tracePoly(ctx, WING_HALF, r * gs, r * gs * spanR, false);
526:         tracePoly(ctx, WING_HALF, r * gs, -r * gs * spanL, true);
527:     }
528:     ctx.fillStyle = SHADOW;
529:     ctx.globalAlpha *= f.shA;
530:     ctx.fill();
531:     ctx.restore();
532: 
533:     // ----- Personnage (sous le planeur) -----
534:     ctx.save();
535:     ctx.translate(p.x, p.y);
536:     ctx.scale(s, s);
537:     ctx.translate(-p.x, -p.y);
538:     drawPlayer(ctx, p, t);
539:     ctx.restore();
540: 
541:     if (gs <= 0.01 && dp >= 1) return;
542: 
543:     // ----- Planeur -----
544:     ctx.save();
545:     ctx.translate(p.x, p.y);
546:     ctx.scale(s, s);
547:     ctx.rotate(aim + yaw);
548:     ctx.translate(0, off);
549:     ctx.lineCap = 'round';
550:     ctx.lineJoin = 'round';
551: 
552:     if (gs > 0.01) {
553:         // Câbles : des épaules du personnage (repère du perso) vers le bord de fuite
554:         const c = Math.cos(-yaw);
555:         const sn = Math.sin(-yaw);
556:         ctx.beginPath();
557:         for (const side of WING_SIDES) {
558:             const ax = r * 0.25;
559:             const ay = side * r * 0.55;
560:             const gx = ax * c - ay * sn;
561:             const gy = ax * sn + ay * c - off;
562:             const sy = side * (side > 0 ? spanR : spanL) * r * gs;
563:             for (let q = 0; q < 2; q++) {
564:                 const u = q === 0 ? 0.3 : 0.62;
565:                 ctx.moveTo(gx, gy);
566:                 ctx.lineTo(r * wingX(u, false) * gs, wingY(u, false) * sy);
567:             }
568:         }
569:         ctx.strokeStyle = 'rgba(10, 16, 48, 0.75)';
570:         ctx.lineWidth = 1.6;
571:         ctx.stroke();
572: 
573:         ctx.save();
574:         ctx.scale(gs, gs);
575:         drawWingTrails(ctx, f, aim + yaw, spanR, spanL);
576:         drawWing(ctx, r, bank, colors, spanR, spanL);
577:         ctx.restore();
578:     }
579: 
580:     // Petit nuage blanc pendant l'ouverture
581:     if (dp < 1) {
582:         const k = 1 - dp;
583:         ctx.beginPath();
584:         for (let i = 0; i < 8; i++) {
585:             const a = (i / 8) * TAU + 0.3;
586:             const px = r * 0.5 + Math.cos(a) * r * (0.4 + dp * 0.9);
587:             const py = Math.sin(a) * r * (0.7 + dp * 2.1);
588:             const pr = r * (0.28 + dp * 0.14);
589:             ctx.moveTo(px + pr, py);
590:             ctx.arc(px, py, pr, 0, TAU);
591:         }
592:         ctx.fillStyle = '#ffffff';
593:         ctx.globalAlpha *= k * 0.75; // remis par le restore juste après
594:         ctx.fill();
595:     }
596:     ctx.restore();
597: }
598: 
599: // Traînées blanches au bout des ailes, à l'opposé du déplacement (sinon vers l'arrière)
600: function drawWingTrails(ctx, f, rot, spanR, spanL) {
601:     const { t, r } = f;
602:     const c = Math.cos(-rot);
603:     const sn = Math.sin(-rot);
604:     const lx = f.vx * c - f.vy * sn; // vitesse dans le repère du planeur
605:     const ly = f.vx * sn + f.vy * c;
606:     let dx = -lx / AIR_SPEED - 0.6;
607:     let dy = -ly / AIR_SPEED;
608:     const dl = Math.hypot(dx, dy) || 1;
609:     dx /= dl;
610:     dy /= dl;
611:     const len = r * (1 + Math.min(1, f.speed / AIR_SPEED) * 1.8);
612:     const ga = ctx.globalAlpha;
613: 
614:     for (const side of WING_SIDES) {
615:         const sy = side * (side > 0 ? spanR : spanL) * r;
616:         // Milieu du bout d'aile (entre bord d'attaque et bord de fuite)
617:         const tx = (r * wingX(1, true) + r * wingX(1, false)) / 2;
618:         const ty = (wingY(1, true) * sy + wingY(1, false) * sy) / 2;
619:         // Filet continu très léger
620:         ctx.beginPath();
621:         ctx.moveTo(tx, ty);
622:         ctx.lineTo(tx + dx * len * 0.7, ty + dy * len * 0.7);
623:         ctx.strokeStyle = 'rgba(255, 255, 255, 0.25)';
624:         ctx.lineWidth = 2;
625:         ctx.stroke();
626:         // Tirets qui défilent vers l'arrière
627:         ctx.strokeStyle = '#ffffff';
628:         for (let i = 0; i < 3; i++) {
629:             const ph = (t * 2.4 + i / 3 + (side > 0 ? 0 : 0.17)) % 1;
630:             const d0 = ph * len;
631:             const d1 = Math.min(len, d0 + len * 0.3);
632:             ctx.beginPath();
633:             ctx.moveTo(tx + dx * d0, ty + dy * d0);
634:             ctx.lineTo(tx + dx * d1, ty + dy * d1);
635:             ctx.globalAlpha = ga * (1 - ph) * 0.65;
636:             ctx.lineWidth = 3 - ph * 1.5;
637:             ctx.stroke();
638:         }
639:         ctx.globalAlpha = ga;
640:     }
641: }
