            playerId: 'usr_' + Math.random().toString(36).substring(2, 9) + Date.now().toString(36),
            created: Date.now()
        };
        try {
            localStorage.setItem(SESSION_KEY, JSON.stringify(session));
        } catch { /* storage full */ }
    }
    return session;
}

