708:                         const victim = fighters.find(f => f.id === msg.targetId);
709:                         if (victim && victim.alive) {
710:                             const mate = remotePlayersMap.get(msg.id) || player;
711:                             combat.damage(victim, msg.damage || 20, mate, false, msg.weaponId || 'ar');
712:                         }
713:                     } else if (msg.type === 'p_state' && msg.id && msg.id !== gameConfig.myPlayerId) {
714:                         let mate = remotePlayersMap.get(msg.id);
715:                         if (!mate) {
716:                             mate = new Player(msg.x || drop.ship.x, msg.y || drop.ship.y);
717:                             mate.id = msg.id;
718:                             mate.name = msg.name || 'Coéquipier';
719:                             mate.team = 1;
720:                             mate.squadSlot = msg.squadSlot || msg.slot || 2;
721:                             mate.isRemote = true;
722:                             remotePlayersMap.set(msg.id, mate);
