728:                         if (msg.squadSlot && mate.squadSlot !== msg.squadSlot) mate.squadSlot = msg.squadSlot;
729:                         if (typeof msg.x === 'number') mate.x = msg.x;
730:                         if (typeof msg.y === 'number') mate.y = msg.y;
731:                         if (typeof msg.vx === 'number') mate.vx = msg.vx;
732:                         if (typeof msg.vy === 'number') mate.vy = msg.vy;
733:                         mate.moving = (Math.hypot(msg.vx || 0, msg.vy || 0) > 20);
734:                         if (typeof msg.angle === 'number') mate.angle = msg.angle;
735:                         if (msg.phase) mate.phase = msg.phase;
736:                         if (typeof msg.altitude === 'number') mate.altitude = msg.altitude;
737:                         if (typeof msg.health === 'number') mate.health = msg.health;
738:                         if (typeof msg.shield === 'number') mate.shield = msg.shield;
739:                         if (typeof msg.slot === 'number') mate.slot = msg.slot;
740:                         if (typeof msg.dbno === 'boolean') {
741:                             if (!mate.dbno && msg.dbno) {
742:                                 mate.dbno = true;
743:                                 effects.death(mate.x, mate.y, mate.colors);
744:                                 SFX.play('playerDown', { x: mate.x, y: mate.y });
745:                                 combatHud?.addKill(null, mate, 'knockout');
746:                             } else if (mate.dbno && !msg.dbno) {
747:                                 mate.dbno = false;
748:                                 effects.healDone(mate.x, mate.y, false);
749:                                 SFX.play('healDone', { x: mate.x, y: mate.y });
750:                             }
