752:                         if (typeof msg.dbnoTimer === 'number') mate.dbnoTimer = msg.dbnoTimer;
753:                         if (mate.health <= 0 && !mate.dbno) mate.alive = false;
754:                     } else if (msg.type === 'p_action' && msg.id && msg.id !== gameConfig.myPlayerId) {
755:                         const mate = remotePlayersMap.get(msg.id);
756:                         if (msg.action === 'jump' && mate) {
757:                             drop.jump(mate);
758:                             SFX.play('jump', { x: mate.x, y: mate.y });
759:                         } else if (msg.action === 'fire' && mate) {
760:                             const hidden = roofAlphaAt(world, mate.x, mate.y) > 0.5;
761:                             if (msg.weaponId === 'melee' || msg.weaponId === 'pickaxe') {
762:                                 if (!hidden) effects.swing(mate.x, mate.y, mate.angle, mate.r);
763:                                 SFX.play('swing', { x: mate.x, y: mate.y });
764:                             } else {
765:                                 if (!hidden) effects.muzzle(mate.x + Math.cos(mate.angle) * 20, mate.y + Math.sin(mate.angle) * 20, mate.angle, msg.weaponId || 'ar');
766:                                 SFX.play('shot', { x: mate.x, y: mate.y, weapon: msg.weaponId || 'ar' });
767:                             }
768:                         } else if (msg.action === 'chest_open' && typeof msg.chestId === 'number') {
769:                             const c = loot.chests[msg.chestId];
770:                             if (c && !c.opened) {
771:                                 loot.openChest(c, mate || null);
772:                             }
773:                         } else if (msg.action === 'loot_pickup' && typeof msg.itemId === 'number') {
774:                             const it = loot.items.find(item => item.id === msg.itemId);
775:                             if (it && !it.gone) {
776:                                 loot._remove(it);
777:                                 effects.pickup(it.x, it.y, loot._itemColor(it));
778:                             }
779:                         } else if (msg.action === 'bot_fire' && !isHost && msg.botId) {
780:                             const b = bots.bots.find(bot => bot.id === msg.botId);
781:                             if (b && b.alive) {
782:                                 const hidden = roofAlphaAt(world, b.x, b.y) > 0.5;
783:                                 if (!hidden) effects.muzzle(b.x + Math.cos(b.angle) * 20, b.y + Math.sin(b.angle) * 20, b.angle, msg.weaponId || 'ar');
784:                                 SFX.play('shot', { x: b.x, y: b.y, weapon: msg.weaponId || 'ar' });
785:                             }
786:                         } else if (msg.action === 'bot_kill' && !isHost && msg.victimId) {
