91:     joinRoom(ws, code, playerData) {
92:         code = String(code || '').trim().toUpperCase();
93:         this.leaveCurrentRoom(ws);
94: 
95:         const room = this.rooms.get(code);
96:         if (!room) {
97:             return this.send(ws, { type: 'error', message: 'Code de salle introuvable.' });
98:         }
99: 
100:         const candidateId = playerData.id || playerData.player?.id;
101: 
102:         // Reconnexion d'un joueur existant (ex: passage à game.html ou refresh)
103:         if (candidateId && room.players.has(candidateId)) {
104:             const existingPlayer = room.players.get(candidateId);
105:             existingPlayer.ws = ws;
106:             existingPlayer.disconnectedAt = null;
107:             this.playerRooms.set(ws, code);
108:             ws.playerId = existingPlayer.id;
109:             console.log(`[Multiplayer] ${existingPlayer.name} (${existingPlayer.id}) reconnecté à la salle ${code} (state: ${room.state})`);
110: 
111:             this.send(ws, {
112:                 type: 'room_joined',
113:                 roomCode: code,
114:                 hostId: room.hostId,
115:                 mode: room.mode,
116:                 botFill: room.botFill,
117:                 slot: existingPlayer.slot,
118:                 seed: room.seed,
119:                 state: room.state,
120:                 players: this.serializePlayers(room)
121:             });
122: 
123:             if (room.state === 'game') {
124:                 this.broadcastToRoom(room, {
125:                     type: 'player_reconnected',
126:                     player: this.serializePlayer(existingPlayer, room),
127:                     id: existingPlayer.id,
128:                     slot: existingPlayer.slot,
129:                     name: existingPlayer.name
130:                 }, ws);
131:             }
132:             return room;
133:         }
134: 
135:         // Si la partie est déjà lancée : rattachement au slot déconnecté
136:         if (room.state === 'game') {
137:             const disconnectedPlayer = [...room.players.values()].find(p => (!p.ws || p.ws.readyState !== 1) && (typeof playerData.slot !== 'number' || p.slot === playerData.slot));
138:             if (disconnectedPlayer) {
139:                 console.log(`[Multiplayer] Rattachement au slot ${disconnectedPlayer.slot} (${disconnectedPlayer.name}) pour ${candidateId || 'reconnexion'}`);
140:                 disconnectedPlayer.ws = ws;
141:                 disconnectedPlayer.disconnectedAt = null;
142:                 this.playerRooms.set(ws, code);
143:                 ws.playerId = disconnectedPlayer.id;
144: 
145:                 this.send(ws, {
146:                     type: 'room_joined',
147:                     roomCode: code,
148:                     hostId: room.hostId,
149:                     mode: room.mode,
150:                     botFill: room.botFill,
151:                     slot: disconnectedPlayer.slot,
152:                     seed: room.seed,
153:                     state: room.state,
154:                     players: this.serializePlayers(room)
155:                 });
156: 
157:                 this.broadcastToRoom(room, {
158:                     type: 'player_reconnected',
159:                     player: this.serializePlayer(disconnectedPlayer, room),
160:                     id: disconnectedPlayer.id,
161:                     slot: disconnectedPlayer.slot,
162:                     name: disconnectedPlayer.name
163:                 }, ws);
164:                 return room;
165:             }
166:             return this.send(ws, { type: 'error', message: 'Cette partie a déjà commencé.' });
167:         }
168: 
169:         if (room.players.size >= MAX_PLAYERS_PER_ROOM) {
170:             return this.send(ws, { type: 'error', message: 'La salle est complète (4 joueurs max).' });
171:         }
172: 
173:         // Trouver un numéro de slot libre (2, 3, ou 4)
174:         const usedSlots = new Set([...room.players.values()].map(p => p.slot));
175:         let freeSlot = 2;
176:         while (usedSlots.has(freeSlot) && freeSlot <= 4) freeSlot++;
177: 
178:         const newPlayer = {
179:             id: candidateId || `p_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
180:             name: String(playerData.name || playerData.player?.name || `Joueur ${freeSlot}`).slice(0, 16),
181:             skin: playerData.skin || playerData.player?.skin || 'recrue',
182:             backpack: playerData.backpack || playerData.player?.backpack || null,
183:             colors: playerData.colors || playerData.player?.colors || null,
184:             pickaxeSkin: playerData.pickaxeSkin || playerData.player?.pickaxeSkin || 'pioche-defaut',
185:             ready: false,
186:             slot: freeSlot,
187:             ws
188:         };
189: 
190:         room.players.set(newPlayer.id, newPlayer);
191:         this.playerRooms.set(ws, code);
192:         ws.playerId = newPlayer.id;
193: 
194:         console.log(`[Multiplayer] ${newPlayer.name} a rejoint la salle ${code} (slot ${freeSlot})`);
195: 
196:         // Ajuster automatiquement le mode selon le nombre de joueurs présents
197:         const count = room.players.size;
198:         let modeChanged = false;
199:         if (count >= 2 && (!room.mode || room.mode === 'solo')) {
200:             room.mode = 'duo';
201:             modeChanged = true;
202:         }
203:         if (count >= 3 && (room.mode === 'solo' || room.mode === 'duo')) {
204:             room.mode = 'trio';
205:             modeChanged = true;
206:         }
207:         if (count >= 4 && room.mode !== 'section') {
208:             room.mode = 'section';
209:             modeChanged = true;
210:         }
211: 
212:         // Confirmer au joueur qu'il a rejoint
213:         this.send(ws, {
214:             type: 'room_joined',
215:             roomCode: code,
216:             hostId: room.hostId,
217:             mode: room.mode,
218:             botFill: room.botFill,
219:             slot: freeSlot,
220:             players: this.serializePlayers(room)
221:         });
222: 
223:         // Notifier les autres joueurs
224:         this.broadcastToRoom(room, {
225:             type: 'player_joined',
226:             player: this.serializePlayer(newPlayer, room)
227:         }, ws);
228: 
229:         // Si le mode a été ajusté automatiquement, diffuser la nouvelle config
230:         if (modeChanged) {
231:             this.broadcastToRoom(room, {
232:                 type: 'room_config',
233:                 mode: room.mode,
234:                 botFill: room.botFill
235:             });
236:         }
237: 
238:         // Vérifier si un changement de joueurs affecte l'état prêt
239:         this.checkRoomReadyState(room);
240: 
241:         return room;
242:     }
