273:         if (!room || room.hostId !== ws.playerId) return;
274: 
275:         // Empêcher de choisir un mode avec moins de places que de joueurs réels dans le groupe
276:         const modeHierarchy = { solo: 1, duo: 2, trio: 3, section: 4 };
277:         if (data.mode && modeHierarchy[data.mode] && modeHierarchy[data.mode] < room.players.size) {
278:             console.log(`[Multiplayer] Mode ${data.mode} rejeté : ${room.players.size} joueurs dans le groupe`);
