304:     checkRoomReadyState(room) {
305:         if (!room || room.state !== 'lobby') return;
306:         const allReady = room.players.size > 0 && [...room.players.values()].every(p => p.ready);
307: 
308:         if (allReady) {
309:             if (room.botFill !== false) {
310:                 // AVEC BOTS : lancement direct avec le duo / équipe en ligne + bots pour le reste
311:                 console.log(`[Multiplayer] Tous prêts dans ${room.code} (Avec bots) : lancement immédiat !`);
312:                 this.startGameForRoom(room);
313:             } else {
314:                 // SANS BOTS : mise en file d'attente matchmaking (nécessite >= 2 équipes)
315:                 console.log(`[Multiplayer] Tous prêts dans ${room.code} (Sans bots) : mise en file d'attente (${room.mode})`);
316:                 this.enqueueMatchmaking(room);
317:             }
318:         } else {
319:             // Un joueur a annulé ou la salle n'est plus prête
320:             this.dequeueMatchmaking(room);
321:         }
322:     }
323: 
324:     enqueueMatchmaking(room) {
325:         const queue = this.getQueue(room.mode);
326:         queue.rooms.add(room.code);
327: 
328:         const teamsCount = queue.rooms.size;
329:         console.log(`[Matchmaking] File ${room.mode}: ${teamsCount} équipes en attente`);
330: 
331:         if (teamsCount < 2) {
332:             // 1 seule équipe : recherche d'adversaires
333:             this.broadcastToRoom(room, {
334:                 type: 'matchmaking_status',
335:                 state: 'searching',
336:                 teamsCount,
337:                 teamsNeeded: 2,
338:                 mode: room.mode
339:             });
340:         } else {
341:             // Au moins 2 équipes : lancer le compte à rebours de 30 secondes !
342:             if (!queue.timer) {
343:                 queue.secondsLeft = 30;
344:                 console.log(`[Matchmaking] >= 2 équipes en ${room.mode} ! Début du chrono de 30 secondes.`);
345: 
346:                 this.broadcastToQueue(queue, {
347:                     type: 'matchmaking_status',
348:                     state: 'countdown',
349:                     secondsLeft: queue.secondsLeft,
350:                     teamsCount: queue.rooms.size,
351:                     mode: room.mode
352:                 });
353: 
354:                 queue.timer = setInterval(() => {
355:                     queue.secondsLeft--;
356: 
357:                     this.broadcastToQueue(queue, {
358:                         type: 'matchmaking_status',
359:                         state: 'countdown',
360:                         secondsLeft: queue.secondsLeft,
361:                         teamsCount: queue.rooms.size,
362:                         mode: room.mode
363:                     });
364: 
365:                     if (queue.secondsLeft <= 0) {
366:                         clearInterval(queue.timer);
367:                         queue.timer = null;
368:                         this.launchMatchmakingGame(room.mode);
369:                     }
370:                 }, 1000);
371:             } else {
372:                 // Compte à rebours déjà en cours : informer la nouvelle équipe
373:                 this.broadcastToRoom(room, {
374:                     type: 'matchmaking_status',
375:                     state: 'countdown',
376:                     secondsLeft: queue.secondsLeft,
377:                     teamsCount: queue.rooms.size,
378:                     mode: room.mode
379:                 });
380:             }
381:         }
382:     }
383: 
384:     dequeueMatchmaking(room, specificMode = null) {
385:         const mode = specificMode || room.mode;
386:         const queue = this.getQueue(mode);
387:         if (!queue.rooms.has(room.code)) return;
388: 
389:         queue.rooms.delete(room.code);
390:         this.broadcastToRoom(room, {
391:             type: 'matchmaking_status',
392:             state: 'idle',
393:             mode
394:         });
395: 
396:         console.log(`[Matchmaking] Salle ${room.code} retirée de la file ${mode}. Restant: ${queue.rooms.size}`);
397: 
398:         if (queue.rooms.size < 2 && queue.timer) {
399:             clearInterval(queue.timer);
400:             queue.timer = null;
401:             queue.secondsLeft = 30;
402:             console.log(`[Matchmaking] Chrono annulé pour ${mode} (moins de 2 équipes).`);
403: 
404:             this.broadcastToQueue(queue, {
405:                 type: 'matchmaking_status',
406:                 state: 'searching',
407:                 teamsCount: queue.rooms.size,
408:                 teamsNeeded: 2,
409:                 mode
410:             });
411:         }
412:     }
