421:     launchMatchmakingGame(mode) {
422:         const queue = this.getQueue(mode);
423:         const roomCodes = [...queue.rooms];
424:         queue.rooms.clear();
425:         if (queue.timer) {
426:             clearInterval(queue.timer);
427:             queue.timer = null;
428:         }
429: 
430:         const validRooms = roomCodes.map(code => this.rooms.get(code)).filter(r => r && r.state === 'lobby');
431:         if (validRooms.length === 0) return;
432: 
433:         const sharedSeed = Math.floor(Math.random() * 1000000);
434:         console.log(`[Matchmaking] Lancement match ${mode} pour ${validRooms.length} équipes (seed: ${sharedSeed})`);
435: 
436:         // Rassembler tous les joueurs réels et leur assigner une équipe par salle
437:         const allMatchPlayers = [];
438:         validRooms.forEach((r, teamIdx) => {
439:             const teamId = teamIdx + 1;
440:             for (const p of r.players.values()) {
441:                 allMatchPlayers.push({
442:                     id: p.id,
443:                     name: p.name,
444:                     skin: p.skin,
445:                     backpack: p.backpack,
446:                     colors: p.colors,
447:                     pickaxeSkin: p.pickaxeSkin,
448:                     ready: p.ready,
449:                     slot: p.slot,
450:                     team: teamId,
451:                     isHost: (p.id === r.hostId)
452:                 });
453:             }
454:         });
455: 
456:         // Relier les salles pour que les messages en cours de partie soient partagés
457:         validRooms.forEach((r, teamIdx) => {
458:             r.state = 'game';
459:             r.seed = sharedSeed;
460:             r.matchedRooms = validRooms;
461: 
462:             this.broadcastToRoom(r, {
463:                 type: 'game_start',
464:                 roomCode: r.code,
465:                 seed: sharedSeed,
466:                 mode: r.mode,
467:                 botFill: false,
468:                 myTeam: teamIdx + 1,
469:                 players: allMatchPlayers
470:             });
471:         });
472:     }
