474:     startGameForRoom(room) {
475:         if (!room || room.state !== 'lobby') return;
476:         this.dequeueMatchmaking(room);
477:         room.state = 'game';
478:         room.seed = Math.floor(Math.random() * 1000000);
479: 
480:         console.log(`[Multiplayer] Lancement de la partie pour la salle ${room.code} (seed: ${room.seed})`);
481: 
482:         const players = this.serializePlayers(room).map(p => ({
483:             ...p,
484:             team: 1 // Tous dans la même équipe
485:         }));
486: 
487:         this.broadcastToRoom(room, {
488:             type: 'game_start',
489:             roomCode: room.code,
490:             seed: room.seed,
491:             mode: room.mode,
492:             botFill: room.botFill !== false,
493:             myTeam: 1,
494:             players
495:         });
496:     }
