526:     relayGameMessage(ws, data) {
527:         const code = this.playerRooms.get(ws);
528:         if (!code) return;
529:         const room = this.rooms.get(code);
530:         if (!room) return;
531: 
532:         // Attacher l'id du joueur émetteur s'il n'est pas déjà précisé
533:         if (!data.id && ws.playerId) data.id = ws.playerId;
534: 
535:         // Relayer aux joueurs de la salle et des salles matchées (si matchmaking multi-équipes)
536:         if (room.matchedRooms && room.matchedRooms.length > 1) {
537:             for (const r of room.matchedRooms) {
538:                 this.broadcastToRoom(r, data, ws);
539:             }
540:         } else {
541:             this.broadcastToRoom(room, data, ws);
542:         }
543:     }
544: 
545:     leaveCurrentRoom(ws) {
546:         const code = this.playerRooms.get(ws);
547:         if (!code) return;
548: 
549:         this.playerRooms.delete(ws);
550:         const room = this.rooms.get(code);
551:         if (!room) return;
552: 
553:         const playerId = ws.playerId;
554:         const player = room.players.get(playerId);
555: 
556:         // IMPORTANT : Si la partie est en cours ('game'), les joueurs changent de page
557:         // (index.html -> game.html), ce qui ferme le socket temporairement.
558:         // On ne supprime PAS le joueur ni la salle tout de suite pour permettre la reconnexion !
559:         if (room.state === 'game') {
560:             if (player) {
561:                 player.ws = null;
562:                 player.disconnectedAt = Date.now();
563:             }
564:             console.log(`[Multiplayer] Joueur ${playerId || 'inconnu'} déconnecté temporairement de la partie ${code}`);
565: 
566:             // Si tous les joueurs sont déconnectés pendant plus de 3 minutes, nettoyer la salle
567:             if (!room.cleanupTimer) {
568:                 room.cleanupTimer = setTimeout(() => {
569:                     const anyConnected = [...room.players.values()].some(p => p.ws && p.ws.readyState === 1);
570:                     if (!anyConnected) {
571:                         console.log(`[Multiplayer] Salle ${code} fermée après inactivité prolongée en jeu`);
572:                         this.rooms.delete(code);
573:                     } else {
574:                         room.cleanupTimer = null;
575:                     }
576:                 }, 180000);
577:             }
578:             return;
579:         }
580: 
581:         room.players.delete(playerId);
582:         console.log(`[Multiplayer] Joueur ${playerId} a quitté la salle ${code}`);
583: 
584:         if (room.players.size === 0) {
585:             console.log(`[Multiplayer] Salle ${code} fermée (vide)`);
586:             this.dequeueMatchmaking(room);
587:             this.rooms.delete(code);
588:             return;
589:         }
590: 
591:         // Si l'hôte part, élire le joueur suivant comme hôte
592:         if (room.hostId === playerId) {
593:             const nextHost = room.players.values().next().value;
594:             if (nextHost) {
595:                 room.hostId = nextHost.id;
596:                 console.log(`[Multiplayer] Nouvel hôte pour ${code} : ${nextHost.name}`);
597:                 this.broadcastToRoom(room, {
598:                     type: 'new_host',
599:                     hostId: nextHost.id
600:                 });
601:             }
602:         }
603: 
604:         this.broadcastToRoom(room, {
605:             type: 'player_left',
606:             playerId,
607:             playerName: player ? player.name : 'Un joueur'
608:         });
609: 
610:         this.checkRoomReadyState(room);
611:     }
