617:             skin: p.skin,
618:             backpack: p.backpack || null,
619:             colors: p.colors,
620:             pickaxeSkin: p.pickaxeSkin,
621:             ready: p.ready,
622:             slot: p.slot,
623:             team: p.team || 1,
624:             isHost: room ? (p.id === room.hostId) : false
625:         };
