632:     send(ws, data) {
633:         if (ws && ws.readyState === 1) { // OPEN
634:             try {
635:                 ws.send(JSON.stringify(data));
636:             } catch (err) {
637:                 console.error('[Multiplayer] Erreur envoi ws:', err.message);
638:             }
