642:     broadcastToRoom(roomOrCode, data, excludeWs = null) {
643:         const room = typeof roomOrCode === 'string' ? this.rooms.get(roomOrCode) : roomOrCode;
644:         if (!room || !room.players) return;
645:         const msg = JSON.stringify(data);
646:         for (const player of room.players.values()) {
647:             if (player.ws && player.ws !== excludeWs && (player.ws.readyState === undefined || player.ws.readyState === 1)) {
648:                 try {
649:                     player.ws.send(msg);
